import { useLayoutEffect, useRef, useState } from "react";
import { extractButtonAction } from "../arrowNavigationHelper";
import { useClearTimers } from "./useClearTimers";
import { useScrollWhileHolding } from "./useScrollWhileHolding";
import { useResize } from "../../hooks/useResize";
export const useHoldOnScroll = () => {
    const scrollableElementRef = useRef(null);
    const timerRef = useRef(null);
    const intervalTimerId = useRef(null);
    const [action, setAction] = useState(null);
    const [isScrollable, setIsScrollable] = useState(true);
    const onMouseDown = (e) => {
        const actionName = extractButtonAction(e);
        if (!actionName) {
            return;
        }
        setAction(actionName);
        timerRef.current = window.setTimeout(() => {
            action && setAction(actionName);
        }, 500);
    };
    const onMouseUp = () => setAction(null);
    useScrollWhileHolding({
        action,
        container: scrollableElementRef.current,
        intervalTimer: intervalTimerId
    });
    useClearTimers({
        action,
        timeoutTimer: timerRef,
        intervalTimer: intervalTimerId
    });
    useLayoutEffect(() => {
        if (scrollableElementRef.current) {
            setIsScrollable(scrollableElementRef.current.clientWidth >= scrollableElementRef.current.scrollWidth);
        }
    }, []);
    useResize(() => {
        if (scrollableElementRef.current) {
            setIsScrollable(scrollableElementRef.current.clientWidth >= scrollableElementRef.current.scrollWidth);
        }
    }, true);
    return { isScrollable, scrollableElementRef, onMouseDown, onMouseUp };
};
